begin;
set local search_path=extensions,public,private;
select no_plan();
insert into auth.sessions(id,user_id) select md5('pgtap-feed:'||id::text)::uuid,id from auth.users on conflict do nothing;
create function pg_temp.feed_member(p_n integer) returns void language plpgsql as $$ declare person uuid:=('10000000-0000-0000-0000-'||lpad(p_n::text,12,'0'))::uuid; begin perform set_config('request.jwt.claim.sub',person::text,true); perform set_config('request.jwt.claim.role','authenticated',true); perform set_config('request.jwt.claims',jsonb_build_object('sub',person,'session_id',md5('pgtap-feed:'||person::text)::uuid,'role','authenticated')::text,true); end $$;
create function pg_temp.feed_staff(p_aal text default 'aal2') returns void language plpgsql as $$ declare person uuid:='90000000-0000-0000-0000-000000000001'; begin perform set_config('request.jwt.claim.sub',person::text,true); perform set_config('request.jwt.claim.role','authenticated',true); perform set_config('request.jwt.claims',jsonb_build_object('sub',person,'session_id',md5('pgtap-feed:'||person::text)::uuid,'role','authenticated','aal',p_aal)::text,true); end $$;
select ok(not has_function_privilege('anon','public.social_feed_posts(uuid,text,integer)','execute'),'anonymous users cannot read member feed');
select ok(not has_table_privilege('authenticated','private.social_feed_posts','select'),'posts use checked projections');
select ok(not has_function_privilege('authenticated','private.social_feed_post_payload(uuid,uuid)','execute'),'unchecked author/media projections stay private');
select ok(not has_function_privilege('authenticated','private.reserve_media_before_social_feed(text,uuid,text,jsonb)','execute'),'renamed upload bypass is private');
select ok(not has_function_privilege('authenticated','private.finish_media_before_social_feed(uuid,uuid,integer,integer,text,text,text)','execute'),'renamed worker bypass is private');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname like 'social_feed_%' and c.relkind='r' and c.relrowsecurity),6::bigint,'all feed tables enable RLS');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'social_feed_%' and p.prosecdef),'public wrappers are invokers');
set local role authenticated;
select pg_temp.feed_member(1);
select throws_ok($$select public.social_feed_staff_save('84000000-0000-4000-8000-000000000001','Group','','active','Test creation')$$,'42501',null::text,'members cannot curate staff directory');
select throws_ok($$select public.social_feed_publish(gen_random_uuid(),null,'')$$,'22023','invalid_social_feed_body','blank text rejected');
select throws_ok($$select public.social_feed_publish(gen_random_uuid(),null,repeat('x',2001))$$,'22023','invalid_social_feed_body','oversized text rejected');
select set_config('test.feed.post',public.social_feed_publish('84100000-0000-4000-8000-000000000001',null,' Hello community ')->>'id',true);
select is(public.social_feed_publish('84100000-0000-4000-8000-000000000001',null,'Hello community')->>'id',current_setting('test.feed.post'),'publication retry returns same post');
select throws_ok($$select public.social_feed_publish('84100000-0000-4000-8000-000000000001',null,'Changed')$$,'23505','social_feed_request_conflict','request cannot change input');
select is(public.social_feed_post(current_setting('test.feed.post')::uuid)->>'body','Hello community','body trims');
select is(public.social_feed_post(current_setting('test.feed.post')::uuid)->'author'->>'id','10000000-0000-0000-0000-000000000001','author is derived from session');
select pg_temp.feed_staff('aal1');
select throws_ok($$select public.social_feed_staff_directory()$$,'42501',null::text,'staff MFA required');
select pg_temp.feed_staff();
select lives_ok($$select public.social_feed_staff_save('84000000-0000-4000-8000-000000000001','Community','Description','active','Synthetic directory fixture')$$,'staff can create directory');
select pg_temp.feed_member(1);
select throws_ok($$select public.social_feed_publish(gen_random_uuid(),'84000000-0000-4000-8000-000000000001','Scoped post')$$,'42501','community_membership_required','scope needs joined membership');
select is((public.social_feed_membership('84000000-0000-4000-8000-000000000001',true)->>'memberCount')::int,1,'join increments actual count');
select is((public.social_feed_membership('84000000-0000-4000-8000-000000000001',true)->>'memberCount')::int,1,'join retry cannot duplicate member');
select set_config('test.feed.scoped',public.social_feed_publish('84100000-0000-4000-8000-000000000002','84000000-0000-4000-8000-000000000001','Scoped post')->>'id',true);
select is(jsonb_array_length(public.social_feed_posts()->'items'),2,'global timeline includes scoped posts');
select pg_temp.feed_member(2);
select is((public.social_feed_like(current_setting('test.feed.post')::uuid,true)->>'likeCount')::int,1,'nonmember may like');
select is((public.social_feed_like(current_setting('test.feed.post')::uuid,true)->>'likeCount')::int,1,'like retry desired state is stable');
select set_config('test.feed.comment',public.social_feed_comment(current_setting('test.feed.scoped')::uuid,'84200000-0000-4000-8000-000000000001','Flat reply')->>'id',true);
select is(public.social_feed_comment(current_setting('test.feed.scoped')::uuid,'84200000-0000-4000-8000-000000000001','Flat reply')->>'id',current_setting('test.feed.comment'),'comment retry recovers same comment');
select pg_temp.feed_member(1);
select throws_ok($$select public.social_feed_report(null,current_setting('test.feed.comment')::uuid,'harassment','Synthetic report',gen_random_uuid())$$,'22023','invalid_social_feed_report','null report target kind cannot poison staff queue');
select pg_temp.feed_member(2);
select throws_ok($$select public.social_feed_delete('post',current_setting('test.feed.post')::uuid)$$,'42501','social_feed_owner_required','nonowner cannot delete post');
select set_config('test.feed.report',public.social_feed_report('post',current_setting('test.feed.post')::uuid,'harassment','Synthetic report','84300000-0000-4000-8000-000000000001')::text,true);
select is(public.social_feed_report('post',current_setting('test.feed.post')::uuid,'harassment','Synthetic report','84300000-0000-4000-8000-000000000001')::text,current_setting('test.feed.report'),'report retries are stable');
select throws_ok($$select public.social_feed_report('post',current_setting('test.feed.scoped')::uuid,'harassment','Synthetic report','84300000-0000-4000-8000-000000000001')$$,'23505','social_feed_request_conflict','report request cannot target another immutable snapshot');
select is(jsonb_array_length(public.social_feed_comments(current_setting('test.feed.scoped')::uuid)->'items'),1,'nonmember can read comments');
select throws_ok($$select public.social_feed_posts(null,'{}',20)$$,'22023','invalid_cursor','cursor requires a complete time/id pair');
select set_config('test.feed.cursor',public.social_feed_posts(null,null,1)->>'nextCursor',true);
select is(jsonb_array_length(public.social_feed_posts(null,current_setting('test.feed.cursor'),1)->'items'),1,'keyset cursor reads next page');
select throws_ok($$select public.reserve_media_upload('social_feed_post',current_setting('test.feed.post')::uuid,'image','{"tags":[]}')$$,'42501','media_target_unavailable','another member cannot attach a picture');
select pg_temp.feed_member(1);
select throws_ok($$select public.reserve_media_upload('social_feed_post',current_setting('test.feed.post')::uuid,'video','{"tags":[]}')$$,'22023','invalid_media_metadata','feed rejects videos');
select set_config('test.feed.upload',public.reserve_media_upload('social_feed_post',current_setting('test.feed.post')::uuid,'image','{"tags":[]}')::text,true);
select is(public.reserve_media_upload('social_feed_post',current_setting('test.feed.post')::uuid,'image','{"tags":[]}')->>'id',current_setting('test.feed.upload')::jsonb->>'id','image reservation retry preserves one pending image');
select is(public.social_feed_post(current_setting('test.feed.post')::uuid)->>'imageStatus','pending','owner can inspect pending review');
select is(public.social_feed_post(current_setting('test.feed.post')::uuid)->>'imagePath',null::text,'pending image has no member path');
select pg_temp.feed_member(2);
select is(public.social_feed_post(current_setting('test.feed.post')::uuid)->>'imageStatus','none','pending image status remains owner-only');
reset role;
update private.media_uploads set status='processing',claim_id='84400000-0000-4000-8000-000000000001',expires_at=clock_timestamp()+interval '10 minutes' where id=(current_setting('test.feed.upload')::jsonb->>'id')::uuid;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.finish_media_upload((current_setting('test.feed.upload')::jsonb->>'id')::uuid,'84400000-0000-4000-8000-000000000001',100,null,'forged/path.jpg',null,null)$$,'22023','invalid_verified_media','worker finalization validates normalized path');
select ok(public.finish_media_upload((current_setting('test.feed.upload')::jsonb->>'id')::uuid,'84400000-0000-4000-8000-000000000001',100,null,current_setting('test.feed.post')||'/'||(current_setting('test.feed.upload')::jsonb->>'id')||'.jpg',null,null),'worker publishes approved image');
set local role authenticated;
select pg_temp.feed_member(2);
select is(public.social_feed_post(current_setting('test.feed.post')::uuid)->>'imageStatus','approved','only approved picture is projected to other members');
select ok(private.social_feed_media_read(current_setting('test.feed.post')||'/'||(current_setting('test.feed.upload')::jsonb->>'id')||'.jpg'),'approved visible post allows storage access');
select lives_ok($$insert into public.blocks(blocker_id,blocked_id) values(auth.uid(),'10000000-0000-0000-0000-000000000001')$$,'block author through existing authorization');
select is(jsonb_array_length(public.social_feed_posts()->'items'),0,'blocking author removes global and scoped posts');
select ok(not private.social_feed_media_read(current_setting('test.feed.post')||'/'||(current_setting('test.feed.upload')::jsonb->>'id')||'.jpg'),'block immediately prevents new storage reads');
select lives_ok($$delete from public.blocks where blocker_id=auth.uid() and blocked_id='10000000-0000-0000-0000-000000000001'$$,'unblock author restores allowed access');
select pg_temp.feed_staff();
select lives_ok($$select public.social_feed_staff_save('84000000-0000-4000-8000-000000000001','Community','Description','archived','Archive synthetic community')$$,'staff archives community');
select pg_temp.feed_member(2);
select is(public.social_feed_community('84000000-0000-4000-8000-000000000001')->>'status','archived','archived history is readable');
select is(jsonb_array_length(public.social_feed_posts('84000000-0000-4000-8000-000000000001')->'items'),1,'archived scoped posts remain readable');
select throws_ok($$select public.social_feed_membership('84000000-0000-4000-8000-000000000001',true)$$,'23514','community_archived','archived community rejects new joins');
select pg_temp.feed_staff();
select lives_ok($$select public.social_feed_staff_save('84000000-0000-4000-8000-000000000001','Community','Description','hidden','Hide synthetic community')$$,'staff hides community');
select pg_temp.feed_member(2);
select throws_ok($$select public.social_feed_post(current_setting('test.feed.scoped')::uuid)$$,'42501','social_feed_unavailable','hidden community removes content');
select is(jsonb_array_length(public.social_feed_posts()->'items'),1,'hidden scope vanishes from global timeline');
select pg_temp.feed_member(1);
select lives_ok($$select public.social_feed_delete('post',current_setting('test.feed.post')::uuid)$$,'author deletes own post');
select lives_ok($$select public.social_feed_delete('post',current_setting('test.feed.post')::uuid)$$,'own delete retry is safe');
reset role;
select is((select social_feed_snapshot->>'body' from public.reports where id=current_setting('test.feed.report')::uuid),'Hello community','report evidence survives own deletion');
select ok(exists(select 1 from private.admin_audit_log where action='community_save' and target_id='84000000-0000-4000-8000-000000000001'),'staff edits are audited');
select * from finish();
rollback;
